local readfile = readfile or function(path)

	local file = filesystem[path];
	if not file or file.type == "folder" then error(("'%s' is not a valid file name"):format(path), 0)  end;

	return file.contents;
end;

local writefile = writefile or function(path, content)

	if (filesystem[path] and filesystem[path].type == "folder") then error(("'%s' is not a valid file name"):format(path), 0); end;
	filesystem[path] = { type = "file"; contents = content; };
end;

local makefolder = makefolder or function(path)

	if filesystem[path] then error(("'%s' is not a valid folder name"):format(path), 0); end;
	if path:sub(-1, -1) == "/" then path = path:sub(1, #path - 1); end;

	filesystem[path] = { type = "folder"; };
end;

local isfile = isfile or function(path)
	return (filesystem[path] and filesystem[path].type == "file") or false;
end;

local isfolder = isfolder or function(path)

	if path:sub(-1, -1) == "/" then path = path:sub(1, #path - 1); end;
	local folder = filesystem[path];

	if not folder then return false; end;
	return folder.type == "folder";
end;

local delfolder = delfolder or function(path)

	if not filesystem[path] or (filesystem[path] and filesystem[path].type == "file") then error(("'%s' is not a valid folder name"):format(path)); end;
	filesystem[path] = nil;
end;

local delfile = delfile or function(path)

	if not filesystem[path] or (filesystem[path] and filesystem[path].type == "folder") then error(("'%s' is not a valid file name"):format(path)); end;
	filesystem[path] = nil;
end;

local listfiles = listfiles or function(path)

	if path:sub(1, 3) == "./" then path = path:sub(4, -1); elseif path:sub(1, 2) == "." then path = path:sub(3, -1); end;
	if not filesystem[path] or (filesystem[path] and filesystem[path].type == "file") then error(("'%s' is not a valid folder name"):format(path)); end;

	local result = {};

	for v in filesystem do
		if v:sub(1, #path) == path and v ~= path then table.insert(result, v); end;
	end;

	return result;
end;

