local attempts, maxAttempts = 0, 5;

function methods:CheckKey(key_str, current_time)

	if attempts > maxAttempts then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);
		methods:SetProgress('    Error: Too much fail attempts.', "ERROR");

		return false, "Too much failed attempts, Please restart luna.xyz.", luna_xyz_env:Notify("Too much failed attempts, Please restart luna.xyz.");
	end;

	local isValid, errorMsg = methods:IsValidText(tostring(key_str));

	if not isValid then
		return false, errorMsg, luna_xyz_env:Notify(tostring(errorMsg));
	end;

	attempts += 1;
	local validation = Junkie.check_key(tostring(key_str));

	if validation.valid then

		luna_xyz_env.script_key = key_str;

		methods:SetProgress('User successfully authenticated. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "READY", true);
		return true, "User successfully authenticated", luna_xyz_env:Notify("User successfully authenticated!");
	end;

	local errorMsg = validation.error or "Unknown error";

	if errorMsg == "KEY_INVALID" or errorMsg == "KEY_EXPIRED" or errorMsg == "ALREADY_USED" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);
		methods:SetProgress('    Error: ' .. tostring(errorMsg), "ERROR");

		return false, errorMsg, luna_xyz_env:Notify("Invalid key or the key is expired.");

	elseif errorMsg == "KEY_INVALIDATED" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (Key was manually disabled)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify("Key was manually disabled.");

	elseif errorMsg == "HWID_BANNED" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (User is banned from luna.xyz)', "ERROR");

		return false, errorMsg, pcall(LP.Kick, LP, 'An error occurred while loading game script.\nError: You are blacklisted from luna.xyz services.\n\nIf you think this is a mistake please contact the support team.\ndiscord.gg/' .. tostring(luna_xyz_env.discord_id) .. '\n');

	elseif errorMsg == "HWID_MISMATCH" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (HWID limit reached)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify("HWID limit reached.");

	elseif errorMsg == "SERVICE_NOT_FOUND" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (Service does not exist or not found)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify("Service does not exist or not found.");

	elseif errorMsg == "SERVICE_MISMATCH" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (Key is for a different service)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify("You are using a key from a different service.");

	elseif errorMsg == "PREMIUM_REQUIRED" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (Premium key required for this service)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify("Premium key required for this service.");

	elseif errorMsg == "ERROR" then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (Network Error)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify('Network error, ERROR: ' .. errorMsg);

	elseif errorMsg:match("^http %d+") then

		methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
		methods:SetProgress('    Error: ' .. tostring(errorMsg) .. ' (Server Error)', "ERROR");

		return false, errorMsg, luna_xyz_env:Notify('Server error, ERROR: ' .. errorMsg);
	end;

	methods:SetProgress('Failed to authenticate user. - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);	
	methods:SetProgress('    Error: ' .. tostring(errorMsg), "ERROR");

	return false, errorMsg, luna_xyz_env:Notify(errorMsg .. ' - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR", true);
end;

