function methods:New(instance, props, children)

	local obj = Instance.new(instance);
	if not props then return obj; end;

	for property, value in pairs(props) do
		obj[property] = value;
	end;

	if not children then return obj; end;

	for _, child in ipairs(children) do
		child.Parent = obj;
	end;

	return obj;
end;

function methods:Hash(str)

	local hash = 2166136261;

	for i = 1, #str do

		hash = bit32.bxor(hash, string.byte(str, i));
		hash = (hash * 16777619) % 2^32;
	end;

	return string.format("%08x", hash);
end;

function methods:HexToRGB(hex)

	hex = hex:gsub("#", "");
	return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16));
end;

function methods:DarkenColor(color, amount)
	return Color3.new( color.R * (1 - amount), color.G * (1 - amount), color.B * (1 - amount));
end;

function methods:IsValidText(str)

	str = str:match("^%s*(.-)%s*$");

	if str == "" then return false, "The text is empty, please enter something."; end;
	if #str < 10 then return false, "The text must contain at least 10 characters."; end;

	return true;
end;

function methods:FadeOut(ui_obj)

	for _, v in pairs(ui_obj:GetDescendants()) do

		if v:IsA("TextLabel") or v:IsA("TextButton") or v:IsA("TextBox") then

			if not v:GetAttribute("TextTransparency") then v:SetAttribute("TextTransparency", v.TextTransparency); end;
			TweenService:Create(v, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = 1 }):Play();

		elseif v:IsA("ImageLabel") or v:IsA("ImageButton") then

			if not v:GetAttribute("ImageTransparency") then v:SetAttribute("ImageTransparency", v.ImageTransparency); end;
			TweenService:Create(v, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { ImageTransparency = 1 }):Play();

		elseif v:IsA("UIStroke") then

			if not v:GetAttribute("Transparency") then v:SetAttribute("Transparency", v.Transparency); end;
			TweenService:Create(v, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Transparency = 1 }):Play();
		end;
	end;
end;

function methods:FadeIn(ui_obj)

	for _, v in pairs(ui_obj:GetDescendants()) do
		if v:IsA("TextLabel") or v:IsA("TextButton") or v:IsA("TextBox") then

			TweenService:Create(v, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = v:GetAttribute("TextTransparency") or 0; }):Play();

		elseif v:IsA("ImageLabel") or v:IsA("ImageButton") then

			TweenService:Create(v, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { ImageTransparency = v:GetAttribute("ImageTransparency") or 0; }):Play();

		elseif v:IsA("UIStroke") then

			TweenService:Create(v, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Transparency = v:GetAttribute("Transparency") or 0; }):Play();
		end;
	end;
end;

function methods:GetAccountAgeDate(AccountAge)

	local dateTable =  DateTime.fromUnixTimestamp(DateTime.now().UnixTimestamp - (AccountAge * 86400)):ToUniversalTime();
	local year, month, day = dateTable.Year, dateTable.Month, dateTable.Day;

	return string.format("%02d/%02d/%04d", month, day, year);
end;

function methods:GetCurrentDate()

	local date = os.date("*t");
	return string.format("%02d-%02d-%04d %02d:%02d:%02d", date.month, date.day, date.year, date.hour, date.min, date.sec);
end;

