----- || METHODS || -----

local progress_total, progress_current = 100, 0;

function methods:SetProgress(message, tag, updateUI, savelog)

	luna_xyz_env.current_log = luna_xyz_env.current_log .. string.format("[%s]: [%s] %s", methods:GetCurrentDate(), tostring(tag), savelog and tostring(message) or tostring(message) .. '\n');

	if getgenv().luna_xyz_debug then	

		if not getgenv().Logger then loadstring(game:HttpGet('https://raw.githubusercontent.com/00lxh/luna_xyz/refs/heads/main/luna_xyz/addons/Logger.lua'))(); end;
		local logger = getgenv().Logger;

		local mapped_tag = tostring(tag == "STARTUP" and "EVENT" or tag == "SUCCESS" and "READY" or tag):lower();
		if logger[mapped_tag] then logger[mapped_tag](message); end;
	end;

	if updateUI then

		progress_current += 1;

		local tween = TweenService:Create(LoadingText, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = 1 });
		tween:Play();

		tween.Completed:Once(function()

			LoadingText.Text = tostring(message);
			TweenService:Create(LoadingText, TweenInfo.new(.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = 0 }):Play();
		end);


		local filled = math.floor((progress_current / progress_total) * progress_total);
		ProgressText.Text = string.rep("#", filled) .. string.rep("-", progress_total - filled);
	end;

	if not savelog then return; end;
	writefile('luna_xyz/logs/' .. tostring(current_date) .. '.log', luna_xyz_env.current_log);
end;

function methods:TogglePages()

	if ContentFrame:WaitForChild("1").Visible then

		methods:FadeOut(ContentFrame:WaitForChild("1"));

		task.wait(.6);
		ContentFrame:WaitForChild("1").Visible = false;

		TweenService:Create(MainFrame.UIScale, TweenInfo.new(1), { Scale = 1.1; }):Play();

		TweenService:Create(TitleFrame.UIScale, TweenInfo.new(1), { Scale = 1.1; }):Play();
		TweenService:Create(ContentFrame.UIScale, TweenInfo.new(1), { Scale = 1.1; }):Play();

		methods:FadeOut(KeyFrame);

		task.wait(.6);

		KeyFrame.Visible = true;
		methods:FadeIn(KeyFrame);

		return;
	end;

	methods:FadeOut(KeyFrame);

	task.wait(.6);
	KeyFrame.Visible = false;

	TweenService:Create(MainFrame.UIScale, TweenInfo.new(1), { Scale = 1; }):Play();

	TweenService:Create(TitleFrame.UIScale, TweenInfo.new(1), { Scale = 1; }):Play();
	TweenService:Create(ContentFrame.UIScale, TweenInfo.new(1), { Scale = 1; }):Play();

	methods:FadeOut(ContentFrame:WaitForChild("1"));

	task.wait(.6);

	ContentFrame:WaitForChild("1").Visible = true;
	methods:FadeIn(ContentFrame:WaitForChild("1"));
end;

