				if not isfile('luna_xyz/' .. tostring(folder_name) .. '/' .. tostring(file_name) .. '/' .. tostring(a)) then				
					methods:SetProgress('The file "luna_xyz/' .. tostring(folder_name) .. '/' .. tostring(file_name) .. '/' .. tostring(a) .. '" was not found, Creaitng a new one..', "DEBUG");	
				end;
			end;

		else

			writefile('luna_xyz/' .. tostring(folder_name) .. '/' .. tostring(file_name), tostring(file_data.content));

			if not isfile('luna_xyz/' .. tostring(folder_name) .. '/' .. tostring(file_name), tostring(file_data.content)) then
				methods:SetProgress('The dile "luna_xyz/' .. tostring(folder_name) .. '/' .. tostring(file_name) .. '" was not found, Creaitng a new one..', "DEBUG");
			end;
		end;
	end;
end;

for _, file_path in pairs(listfiles("luna_xyz/logs")) do

	current_time_v2 = os.time();

	local filename = tostring(file_path):match("([^\\]+)$");
	filename = filename:match("(.+)%..+$");

	local months, days, years = filename:match("(%d+)%-(%d+)%-(%d+)");
	if not(months or days or years) then continue; end;

	local fileTime = os.time({ year = years, month = months, day = days });
	local difference = os.difftime(os.time(), fileTime);

	local delete_days = 10;

	if difference >= (delete_days * 24 * 60 * 60) then 

		methods:SetProgress('Deleting log file "' .. tostring(file_path):gsub("\\", "/") .. '" because is 10 days old. - (' .. string.format("%.2f", os.time() - current_time_v2) .. ')', "DELETE");
		delfile(file_path);
	end;
end;

