function luna_xyz_env:GetService(s)

	if luna_xyz_env.loaded_libs[s] then return luna_xyz_env.loaded_libs[s]; end;

	local __s, __d = pcall(function()
		return cloneref(game:GetService(s));
	end);

	if __s then return __d; end;
	return error('The Service "'  .. tostring(s) .. '" does not exist, did you check the grammar?');
end;

function luna_xyz_env:Notify(t, d)

	luna_xyz_env:GetService("Library"):Notify({
		Title = 'luna.xyz - ' .. tostring(hub_versions.luna_hub); Description = tostring(t); Time = d;
	});
end;

function luna_xyz_env:DiscordInvite()

	setclipboard(tostring(luna_xyz_env.discord_id));
	luna_xyz_env:Notify("Discord invitation copied to clipboard.");

	make_request({

		Url = 'http://127.0.0.1:6463/rpc?v=1'; Method = 'POST';
		Headers = { ['Content-Type'] = 'application/json'; Origin = 'https://discord.com/'; };

		Body = HttpService:JSONEncode({ cmd = 'INVITE_BROWSER'; nonce = HttpService:GenerateGUID(false); args = { code = tostring(luna_xyz_env.discord_id); } });
	});
end;

function luna_xyz_env:GetCache()
	return luna_xyz_env.cache_folder;
end;

