current_time = os.time();
methods:SetProgress("Fetching hub modules..", "DEBUG", true);

for moduleName, moduleUrl in pairs(modules_list) do

	current_time_v2 = os.time();
	methods:SetProgress('Checking module: ' .. moduleName, "DEBUG", true);

	local local_file = 'luna_xyz/modules/' .. moduleName .. '.lua';
	local cache  = hash_cache[moduleName];

	local __s, __d = pcall(game.HttpGet, game, moduleUrl);

	if not __s then		

		methods:SetProgress('Failed to fetch module ' .. moduleName .. '.lua - (' .. string.format("%.2f", os.time() - current_time_v2) .. ')', "ERROR", true);
		methods:SetProgress('    Error: ' .. tostring(__d), "ERROR");

		break;
	end;

	local remoteHash = methods:Hash(__d);

	local needsUpdate = not cache or cache.hash ~= remoteHash or cache.url  ~= moduleUrl or not isfile(local_file);

	if needsUpdate then

		current_time_v3 = os.time();

		hash_cache[moduleName] = { hash = remoteHash; url  = moduleUrl; time = os.time(); };
		writefile("luna_xyz/hash_cache.json", HttpService:JSONEncode(hash_cache));

		writefile(local_file, __d);
		methods:SetProgress('Module ' .. moduleName ..  '.lua updated. - (' .. string.format("%.2f", os.time() - current_time_v3) .. ')', "DEBUG", true);
	end;

	local __s, __d = pcall(function()
		return loadstring(readfile(local_file))();
	end);

	if not __s then

		methods:SetProgress('Failed to load module ' .. moduleName .. '.lua - (' .. string.format("%.2f", os.time() - current_time_v2) .. ')', "ERROR", true);
		methods:SetProgress('    Error: ' .. tostring(__d), "ERROR");

		break;
	end;

	luna_xyz_env.loaded_libs[moduleName] = __d;
	methods:SetProgress('Module loaded ' .. moduleName .. '.lua - (' .. string.format("%.2f", os.time() - current_time_v2) .. ')', "READY", true);
end;

