		end);

		if __s then

			task.spawn(function()

				TweenService:Create(MainFrame.UIScale, TweenInfo.new(1), { Scale = 0; }):Play();
				task.wait(1); UI:Destroy();
			end);

			methods:SetProgress(tostring(i) .. ' script loaded successfully! - (' .. string.format("%.2f", os.time() - current_time) .. ')', "SUCCESS", false, true);
			luna_xyz_env.current_log = "00._lxh was here<3";

			return methods:CreateLog(i);
		end;

		methods:SetProgress('Error loading game script ' .. tostring(i) .. '.lua - (' .. string.format("%.2f", os.time() - current_time) .. ')', "ERROR");
		methods:SetProgress('    Error: ' .. tostring(__d), "ERROR");

